function grid$sysrighthrempinfo(f){
  this.constructor(f);
}
grid$sysrighthrempinfo.prototype = new DirEvent();
grid$sysrighthrempinfo.prototype.afterInit = function(){
  var p = this._dir;
  p.options.buttonGridKeys[69] = 'permission';
  if (p.options._xtype == 1)
    p.options.dirController = 'sysuserinfo';
  else
    p.options.dirController = 'sysgroupinfo';
}
grid$sysrighthrempinfo.prototype.formActionChange = function(action, m){
  var p = this._dir;
  if (p.options._xtype == 0 && action == 'BeforeShowViewDir') {
    m.get('user_id').Name = 'group_id';
  }
  return true;
}
grid$sysrighthrempinfo.prototype.beforeButtonGridClick = function(id, gindex){
  var p = this._dir, dt = p.grid().data;
  if (id == 'permission') {
    var r = p.curr("r", undefined, gindex);
    if (r != null) {
      p.request('CheckRight', '', [['user_id', 'C', dt.val(r, 'user_id')]], function(p, d, run){
        if (run) {
          p.showFilter('sysrighthrempinfo2', null, {backdropclick: false});
        }
      })
      return false;
    }
  }
  return true
}
